INSERT INTO quizzes (id, title, subject, difficulty, description) VALUES (1, 'Frontend Development', 'Web Development', 'medium', 'JavaScript, TypeScript, React, CSS and the web platform.');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (1, 1, 1, 'true-false', 'An `async` function always returns a Promise, even if its body returns a plain value like `return 5`.', 'True', 'An `async` function wraps its result in a Promise. `return 5` resolves the returned Promise with `5`; throwing rejects it. To read the value you must `await` it or use `.then`.', 'codeprep', 'js-tf-async-returns-promise');
INSERT INTO question_options (question_id, position, option_text) VALUES (1, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (1, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (2, 1, 2, 'true-false', '`Promise.all([...])` rejects as soon as any input promise rejects, without waiting for the others to settle.', 'True', '`Promise.all` short-circuits on the first rejection and rejects immediately with that reason; the other promises keep running but their results are ignored. Use `Promise.allSettled` when you need every outcome regardless of failures.', 'codeprep', 'js-tf-promise-all-rejects-fast');
INSERT INTO question_options (question_id, position, option_text) VALUES (2, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (2, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (3, 1, 3, 'multiple-choice', 'What does the type `string | number` mean for a variable?', 'Its value may be a `string` OR a `number` at any given time', 'A union type `A | B` means the value is one of the constituent types at any moment. To use type-specific members you must first narrow it (e.g. with `typeof`). An intersection (`A & B`) would require both at once.', 'codeprep', 'ts-mcq-union-type-meaning');
INSERT INTO question_options (question_id, position, option_text) VALUES (3, 1, 'Its value may be a `string` OR a `number` at any given time');
INSERT INTO question_options (question_id, position, option_text) VALUES (3, 2, 'Its value must be both a `string` and a `number` simultaneously');
INSERT INTO question_options (question_id, position, option_text) VALUES (3, 3, 'It is an array containing strings and numbers');
INSERT INTO question_options (question_id, position, option_text) VALUES (3, 4, 'It is a `string` that can be converted to a `number`');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (4, 1, 4, 'multiple-choice', 'What is a `.d.ts` declaration file?', 'A file containing only type declarations — no runtime code — that lets the compiler type-check usage of a library implemented in plain JavaScript', 'A `.d.ts` file holds *ambient* declarations (`declare …`): pure type information with no executable code, so it contributes nothing to the emitted JavaScript. It describes the shape of values that exist elsewhere — typically a plain-JS library — so the checker can verify your usage. Publishing a `.d.ts` next to compiled JS (referenced from the package\'s `types` field) is how packages ship their own types. The build cache is `.tsbuildinfo`, not `.d.ts`.', 'codeprep', 'ts-mcq-dts-purpose');
INSERT INTO question_options (question_id, position, option_text) VALUES (4, 1, 'A file containing only type declarations — no runtime code — that lets the compiler type-check usage of a library implemented in plain JavaScript');
INSERT INTO question_options (question_id, position, option_text) VALUES (4, 2, 'A compiled bundle that packages a library\'s JavaScript implementation together with its types in one file');
INSERT INTO question_options (question_id, position, option_text) VALUES (4, 3, 'A per-package configuration file that tells the compiler which strict checks to apply to that dependency');
INSERT INTO question_options (question_id, position, option_text) VALUES (4, 4, 'An incremental-build cache the compiler writes to speed up subsequent compilations');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (5, 1, 5, 'multiple-choice', 'For `const u: { name?: string } = {}`, what is the type of `u.name?.toUpperCase()`?', '`string | undefined`', 'Optional chaining short-circuits to `undefined` when `u.name` is `undefined`, otherwise it yields the `string` result of `.toUpperCase()`. The overall type is therefore `string | undefined`.', 'codeprep', 'ts-mcq-optional-chaining-type');
INSERT INTO question_options (question_id, position, option_text) VALUES (5, 1, '`string | undefined`');
INSERT INTO question_options (question_id, position, option_text) VALUES (5, 2, '`string`');
INSERT INTO question_options (question_id, position, option_text) VALUES (5, 3, '`undefined`');
INSERT INTO question_options (question_id, position, option_text) VALUES (5, 4, 'It is a compile error because `name` may be undefined');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (6, 1, 6, 'true-false', 'Given `type UserId = { id: number }` and `type OrderId = { id: number }`, a value typed `UserId` is assignable to `OrderId` (and vice versa), even though they were declared independently.', 'True', 'TypeScript compatibility is structural: two types with the same shape are mutually assignable regardless of their names or where they were declared (unlike nominal systems such as Java or C#). The one wrinkle is that a *fresh object literal* assigned directly to a typed target additionally undergoes excess property checking. To make same-shaped ids distinct, add a brand, e.g. `type UserId = { id: number; __brand: \'user\' }`.', 'codeprep', 'ts-tf-structural-assignability');
INSERT INTO question_options (question_id, position, option_text) VALUES (6, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (6, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (7, 1, 7, 'short-answer', 'What is a discriminated union and why is it useful?', 'A discriminated (tagged) union is a union of object types that share a common literal property — the discriminant. Switching on that property lets TypeScript narrow the value to one exact member, so you can handle each case type-safely and get exhaustiveness checking for free.', 'The shared literal field (e.g. `type: \'circle\' | \'square\'`) is what lets the compiler narrow inside a `switch`. Adding a `never` default then enforces that every member is handled.', 'codeprep', 'ts-sa-discriminated-union');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (8, 1, 8, 'true-false', 'Two `interface Box {}` declarations with the same name in the same scope merge into a single interface combining their members.', 'True', 'Declaration merging: multiple interface declarations of the same name in the same scope are combined into one. This is how ambient types like `Window` are augmented. Type aliases do not merge — a duplicate `type` name is an error.', 'codeprep', 'ts-tf-interface-merging');
INSERT INTO question_options (question_id, position, option_text) VALUES (8, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (8, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (9, 1, 9, 'multiple-choice', 'How does a TypeScript 5.0 standard (TC39 Stage 3) decorator differ from a legacy `experimentalDecorators` one?', 'A standard decorator is called as `(value, context)` where `context` carries `kind`, `name`, `addInitializer`, etc.; it has no parameter-index form and no built-in metadata argument, unlike the legacy `(target, key, descriptor)` shape', 'TS 5.0 implemented the TC39 Stage 3 decorator proposal. A standard decorator receives two arguments: the decorated `value` (the method, the class, an accessor pair, etc.) and a `context` object describing it (`kind`, `name`, `static`, `private`, `addInitializer`, and accessors). This differs from the legacy `experimentalDecorators` form `(target, propertyKey, descriptor)`. Standard decorators have no parameter decorators (parameter decorators stay legacy-only) and no built-in `reflect-metadata` argument — the `emitDecoratorMetadata` mechanism belongs to the legacy implementation.', 'codeprep', 'ts-mcq-standard-decorator-signature');
INSERT INTO question_options (question_id, position, option_text) VALUES (9, 1, 'A standard decorator is called as `(value, context)` where `context` carries `kind`, `name`, `addInitializer`, etc.; it has no parameter-index form and no built-in metadata argument, unlike the legacy `(target, key, descriptor)` shape');
INSERT INTO question_options (question_id, position, option_text) VALUES (9, 2, 'Standard decorators still use `(target, propertyKey, descriptor)` but rename the third argument to `context`');
INSERT INTO question_options (question_id, position, option_text) VALUES (9, 3, 'Standard decorators can only be applied to classes, never to methods or fields');
INSERT INTO question_options (question_id, position, option_text) VALUES (9, 4, 'Standard and legacy decorators are byte-for-byte identical; the 5.0 change was purely internal to the compiler');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (10, 1, 10, 'multiple-choice', 'When does the effect in `useEffect(fn, [])` run?', 'After the first render (on mount), and never again', 'An empty dependency array means the effect has no dependencies that change, so it runs once after mount. Its optional cleanup runs on unmount.', 'codeprep', 'react-mcq-useeffect-empty-deps');
INSERT INTO question_options (question_id, position, option_text) VALUES (10, 1, 'After the first render (on mount), and never again');
INSERT INTO question_options (question_id, position, option_text) VALUES (10, 2, 'After every render');
INSERT INTO question_options (question_id, position, option_text) VALUES (10, 3, 'Synchronously before the first render');
INSERT INTO question_options (question_id, position, option_text) VALUES (10, 4, 'Only when the component unmounts');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (11, 1, 11, 'multiple-choice', 'Immediately after calling `setCount(count + 1)`, what does reading `count` on the next line return (within the same event handler)?', 'The old value — the state variable does not change until the next render', 'State setters schedule a re-render; they do not mutate the existing `count` binding. Within the same render/handler `count` keeps its current value, and the updated value is only visible in the next render. This is why updater functions are needed for sequential updates.', 'codeprep', 'react-mcq-usestate-async-batching');
INSERT INTO question_options (question_id, position, option_text) VALUES (11, 1, 'The old value — the state variable does not change until the next render');
INSERT INTO question_options (question_id, position, option_text) VALUES (11, 2, 'The new value, because `setCount` updates `count` synchronously');
INSERT INTO question_options (question_id, position, option_text) VALUES (11, 3, '`undefined`, because state is cleared during the update');
INSERT INTO question_options (question_id, position, option_text) VALUES (11, 4, 'It depends on whether the component is wrapped in `React.memo`');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (12, 1, 12, 'true-false', 'Assigning a new value to a ref\'s `.current` (e.g. `ref.current = 5`) does not trigger a re-render.', 'True', 'A ref is a mutable container whose `.current` you can read and write without React tracking it, so mutating it never schedules a render. That is exactly why refs suit values you want to persist across renders without causing one (timer ids, DOM nodes, previous values).', 'codeprep', 'react-tf-ref-mutation-no-rerender');
INSERT INTO question_options (question_id, position, option_text) VALUES (12, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (12, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (13, 1, 13, 'multiple-choice', 'What does `const [state, formAction, isPending] = useActionState(action, initialState)` give you?', 'It wraps an async action so React tracks the pending flag and the value the action returns, exposing both as state plus a `formAction` to wire to a `<form>`', '`useActionState` is built for form/action UX: you give it an action `(previousState, formData) => newState` and an initial state, and it returns the latest returned state, a wrapped `formAction` to pass to `<form action={…}>` (or a button `formAction`), and an `isPending` boolean while the action runs. That removes the boilerplate of a separate `useState` for the result plus a `useState`/`useTransition` for the pending flag. It is not a memoizer (`useCallback`), not a global store, and it does not run once-and-cache.', 'codeprep', 'react-mcq-useactionstate-purpose');
INSERT INTO question_options (question_id, position, option_text) VALUES (13, 1, 'It memoizes `action` so its identity is stable across renders, like `useCallback`');
INSERT INTO question_options (question_id, position, option_text) VALUES (13, 2, 'It wraps an async action so React tracks the pending flag and the value the action returns, exposing both as state plus a `formAction` to wire to a `<form>`');
INSERT INTO question_options (question_id, position, option_text) VALUES (13, 3, 'It registers a global reducer that every component in the tree can dispatch to');
INSERT INTO question_options (question_id, position, option_text) VALUES (13, 4, 'It runs `action` once on mount and caches the result for the component\'s lifetime');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (14, 1, 14, 'multiple-choice', 'Given several `<button class="btn">` elements, what does `document.querySelector(".btn")` return?', 'The first matching element, or `null` if none match', '`querySelector` returns only the first element matching the CSS selector (in document order), or `null` if there are no matches. To get all matches use `querySelectorAll`, which returns a static `NodeList`.', 'codeprep', 'web-mcq-queryselector-first');
INSERT INTO question_options (question_id, position, option_text) VALUES (14, 1, 'The first matching element, or `null` if none match');
INSERT INTO question_options (question_id, position, option_text) VALUES (14, 2, 'A live `HTMLCollection` of all matching elements');
INSERT INTO question_options (question_id, position, option_text) VALUES (14, 3, 'A static `NodeList` of all matching elements');
INSERT INTO question_options (question_id, position, option_text) VALUES (14, 4, 'An array of all matching elements');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (15, 1, 15, 'multiple-choice', 'You have `<div id="menu" popover>…</div>`. Using only HTML (no JavaScript), how do you make a `<button>` toggle it open and closed?', '`<button popovertarget="menu">Toggle</button>`', 'A control button declares the popover it operates with `popovertarget="<id>"`; by default the action is `toggle`, so the same button shows and hides it with no script. You can narrow the action with `popovertargetaction="show"` or `"hide"`. `popover` is the attribute on the popover element itself (not the button), `for` is for `<label>`, and `aria-controls` only describes the relationship for assistive tech — it wires up no behavior.', 'codeprep', 'web-mcq-popover-invoker-attribute');
INSERT INTO question_options (question_id, position, option_text) VALUES (15, 1, '`<button popovertarget="menu">Toggle</button>`');
INSERT INTO question_options (question_id, position, option_text) VALUES (15, 2, '`<button popover="menu">Toggle</button>`');
INSERT INTO question_options (question_id, position, option_text) VALUES (15, 3, '`<button for="menu">Toggle</button>`');
INSERT INTO question_options (question_id, position, option_text) VALUES (15, 4, '`<button aria-controls="menu">Toggle</button>`');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (16, 1, 16, 'true-false', 'Data written to `sessionStorage` in one tab is automatically visible in another tab open to the same origin.', 'False', '`sessionStorage` is scoped to a single tab/browsing context and is cleared when that tab closes, so other tabs cannot see it. `localStorage` is the one shared across all tabs of the same origin and persists until explicitly cleared.', 'codeprep', 'web-tf-sessionstorage-not-shared-across-tabs');
INSERT INTO question_options (question_id, position, option_text) VALUES (16, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (16, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (17, 1, 17, 'multiple-choice', 'In a single-page app router, what happens immediately when you call `history.pushState(state, "", "/profile")`?', 'The address bar changes to `/profile` and a new history entry is pushed — no navigation, no server request, and no `popstate`; `popstate` only fires later on back/forward', '`pushState` is purely a history/URL mutation: the address bar updates and an entry is pushed, but the document stays put — no unload, no network request, and no History-API event fires, so the router must render the new view itself right after calling it (the newer Navigation API\'s `navigate` event is the one exception that does fire). `popstate` fires only on history *traversal* (back/forward, `history.back()`), not on `pushState`/`replaceState`. Because the server never sees these client-side URLs, deep-linking or refreshing on `/profile` hits the server cold — which is why SPA hosting needs a catch-all rewrite to `index.html`.', 'codeprep', 'web-mcq-pushstate');
INSERT INTO question_options (question_id, position, option_text) VALUES (17, 1, 'The browser navigates to `/profile`, requesting it from the server like a normal link click, and the single-page app reloads from scratch');
INSERT INTO question_options (question_id, position, option_text) VALUES (17, 2, 'A `popstate` event fires right away, which is how the router knows to render the new route');
INSERT INTO question_options (question_id, position, option_text) VALUES (17, 3, 'The address bar changes to `/profile` and a new history entry is pushed — no navigation, no server request, and no `popstate`; `popstate` only fires later on back/forward');
INSERT INTO question_options (question_id, position, option_text) VALUES (17, 4, 'Nothing visible changes until the next reload; the URL update is deferred');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (18, 1, 18, 'true-false', 'Wrapping a same-document DOM update in `document.startViewTransition(() => updateDOM())` will silently break the update in browsers that don\'t support the View Transitions API.', 'False', 'It does not break, but you must guard it: `document.startViewTransition` is simply `undefined` in unsupporting browsers, so calling it throws. The standard pattern feature-detects — `if (!document.startViewTransition) { updateDOM(); return; } document.startViewTransition(updateDOM);` — so the DOM still updates everywhere, just without the animation where it isn\'t supported. That\'s progressive enhancement: the transition is a visual upgrade, never a requirement for the content to change.', 'codeprep', 'web-tf-view-transition-progressive');
INSERT INTO question_options (question_id, position, option_text) VALUES (18, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (18, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (19, 1, 19, 'short-answer', 'Why does the same-document View Transitions API require you to make the DOM change *inside* the callback passed to `startViewTransition`, rather than updating the DOM yourself and then calling it?', 'Because the API needs to capture both the before and after states, and the callback is its hook for the moment in between. When you call `startViewTransition(cb)`, the browser first snapshots the current (old) visual state, then runs your callback to mutate the DOM, then snapshots the new state, and animates from old to new. If you mutated the DOM first and only then called `startViewTransition`, the \'old\' snapshot would already be the new layout — there\'d be nothing to animate from, so you\'d get no transition (or a broken one). Putting the mutation in the callback is what lets the browser bracket it with the two snapshots.', 'The callback is a synchronization point, not just a convenience. The browser must own the timing so it can sandwich the DOM mutation between an old-state capture and a new-state capture; surrendering that ordering (mutating outside) destroys the \'from\' state the animation interpolates out of. This is also why the callback can return a promise — the browser waits for the new state to settle before capturing it.', 'codeprep', 'web-sa-view-transition-why-callback');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (20, 1, 20, 'multiple-choice', 'A badge is styled with explicit dimensions, but renders at its text\'s natural size:\n\n```css\nspan.badge {\n  width: 200px;\n  height: 40px;\n}\n```\n\nWhy do `width` and `height` have no effect here?', 'A `<span>` is `display: inline`, and inline boxes are sized by their content — `width` and `height` don\'t apply until the display changes (e.g. to `inline-block` or `block`)', 'Non-replaced inline boxes are sized by the text and line boxes they generate: `width`, `height`, and vertical margins simply do not apply to them. The fix is to change the display — `inline-block` keeps the badge flowing in text while making it respect explicit dimensions, and `block` works if it should stand on its own line. Positioning is irrelevant (`width` works fine on static block elements), the UA stylesheet doesn\'t override author declarations this way, and `box-sizing` only changes what `width` *measures*, not whether it applies.', 'codeprep', 'css-mcq-inline-width-ignored');
INSERT INTO question_options (question_id, position, option_text) VALUES (20, 1, '`width` and `height` only apply to elements with a `position` other than `static`');
INSERT INTO question_options (question_id, position, option_text) VALUES (20, 2, 'A `<span>` is `display: inline`, and inline boxes are sized by their content — `width` and `height` don\'t apply until the display changes (e.g. to `inline-block` or `block`)');
INSERT INTO question_options (question_id, position, option_text) VALUES (20, 3, 'The browser\'s user-agent stylesheet overrides author-specified dimensions on `<span>` elements');
INSERT INTO question_options (question_id, position, option_text) VALUES (20, 4, '`width` on a `<span>` only takes effect when `box-sizing: border-box` is set');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (21, 1, 21, 'true-false', '`1vh` is equal to 1% of the viewport\'s height.', 'True', '`vh` is a viewport-percentage unit: `1vh` equals 1% of the viewport height, so `100vh` is the full viewport height. (On mobile, `vh` is sized to the *large* viewport and can sit behind the browser\'s collapsing toolbars, which is why the newer `svh`/`lvh`/`dvh` units exist — but the 1%-of-viewport-height definition still holds.)', 'codeprep', 'css-tf-vh-includes-mobile-bars');
INSERT INTO question_options (question_id, position, option_text) VALUES (21, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (21, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (22, 1, 22, 'short-answer', 'Why might you prefer `oklch()` (or `oklab()`) over `hsl()` or hex when building a design system\'s color palette and generating tints/shades programmatically?', 'oklch is perceptually uniform: its lightness channel tracks how bright a color actually looks, and equal numeric steps look like equal visual steps, so you can derive consistent tints and shades by nudging one channel and trust them to read evenly. hsl\'s lightness is not perceptually even — the same lightness value looks much brighter for yellow than for blue — so palettes generated from it come out lopsided. oklch also addresses the wider Display-P3 gamut, letting you specify more vivid colors than sRGB hex can express, and mixing/interpolating in it avoids the muddy midpoints sRGB produces.', 'oklch/oklab are perceptually uniform spaces where the `L` channel corresponds to perceived brightness and equal numeric changes produce equal perceived changes. That makes algorithmic palette generation reliable: a single lightness scale yields tints and shades that look evenly spaced across every hue, which hsl can\'t promise because its lightness is wildly non-uniform between hues. They also reach the wider P3 gamut for more saturated colors than sRGB hex, and interpolation/mixing in oklch produces natural-looking gradients without the dark or grayish midpoints sRGB interpolation suffers from.', 'codeprep', 'css-sa-oklch-theming-advantage');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (23, 1, 23, 'short-answer', 'Two elements overlap. Walk through the model the browser uses to decide which one paints in front: what kinds of properties create a stacking context, how a stacking context\'s contents are painted relative to elements outside it, and which other elements a given `z-index` value is actually compared against.', 'A stacking context is created by a positioned element with a non-`auto` `z-index`, and unconditionally by properties like `opacity` below 1, `transform`, `filter`, `isolation: isolate`, and `position: fixed`/`sticky` (flex and grid items also get one from a non-`auto` `z-index` alone). Each stacking context is painted atomically: all of its descendants are flattened and sandwiched together as one unit, so an element from outside the context can never be drawn between two elements inside it. Within a context, children are layered by their `z-index` (negative levels behind, then the normal-flow content, then positive levels in front). Crucially, that comparison is local: an element\'s `z-index` only competes with the other children of its nearest ancestor stacking context, and where that whole group sits on the page is decided by the ancestor\'s own stacking level among *its* siblings — which is why a huge `z-index` deep in the tree can still lose to a modest one higher up.', 'Paint order is resolved per stacking context, not globally. A context is formed by a positioned element with non-`auto` `z-index` and unconditionally by `opacity < 1`, `transform`, `filter`, `isolation: isolate`, `position: fixed`/`sticky`, and friends. The browser paints each context as an atomic unit — its descendants are sandwiched together, and nothing from outside can interleave between them. A `z-index` therefore only ranks an element against the other children of its nearest ancestor stacking context; that ancestor\'s own level decides where the whole unit sits one tier up. This local-competition rule is the root cause of every "my z-index: 9999 is ignored" bug.', 'codeprep', 'css-sa-stacking-context-formation');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (24, 1, 24, 'true-false', '`z-index` only has an effect on elements whose `position` is something other than `static`.', 'False', 'This was true in the original CSS 2 model, but the Flexbox and Grid specs added an exception: flex items and grid items respect `z-index` even when their `position` is `static`. A non-`auto` `z-index` on a flex or grid item changes its paint order against overlapping siblings and creates a stacking context, exactly as it would on a positioned element. So overlapping grid items (e.g. stacked in the same grid area) can be reordered with `z-index` alone — no `position: relative` needed. Outside flex/grid layout, the old rule still holds: on a static block element, `z-index` is ignored.', 'codeprep', 'css-tf-zindex-flex-grid-items');
INSERT INTO question_options (question_id, position, option_text) VALUES (24, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (24, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (25, 1, 25, 'short-answer', 'A button\'s `color` is declared in two places: a heavy `#app .btn.primary` rule inside `@layer components`, and a plain `button` rule in the page\'s stylesheet outside any layer — and the browser\'s built-in (user-agent) stylesheet sets its own value too. The plain `button` rule wins, and selector weight had nothing to do with it. Walk through, in order, the full sequence of checks the cascade runs to pick a winning declaration, and explain why comparing specificity is one of the LAST things the browser does — what gets consulted before specificity ever comes into play, and where do `!important` and source order fit?', 'The cascade is a pipeline, and specificity sits in the middle of it, not at the top. Step 1 is origin and importance: declarations are bucketed by where they come from — the browser\'s user-agent stylesheet, user styles, and author (page) styles. For normal declarations, author beats user beats user-agent; for `!important` declarations that ranking REVERSES, which is why a user-agent `!important` rule can never be overridden by a page. Step 2, within the author origin, is cascade layers: `@layer` blocks are ranked by declaration order, with later layers beating earlier ones for normal declarations (reversed again under `!important`), and crucially, for normal declarations unlayered author styles beat every layered one (under `!important` this also reverses: an important layered declaration beats an important unlayered one). That\'s exactly why the plain `button` rule wins here — it\'s unlayered, the `#app .btn.primary` rule lives inside a layer, and the comparison ends before any selector is examined. Step 3, only between declarations that survive with the same origin and layer standing, is specificity (with inline `style=""` ranking above all selectors). Step 4, the final tiebreaker when specificity is equal, is source order — the later declaration wins.', 'The mental model most people carry — "highest specificity wins, plus !important as a trump card" — describes only the middle of the algorithm. The cascade actually filters in this order: (1) origin & importance — user-agent < user < author for normal declarations, with the order reversed for `!important` ones, so UA `!important` outranks everything a page can write; (2) cascade layers within the author origin — later-declared layers beat earlier ones for normal declarations (reversed under `!important`), and unlayered author styles beat all layered styles for normal declarations — under `!important` that flips too, with layered important declarations winning. This is the whole design point of `@layer`: a framework shipped in a layer can never out-muscle the consuming app\'s plain CSS no matter how specific its selectors are; (3) specificity — only consulted between declarations that tied on origin and layer, with inline `style` attributes ranking above any selector; (4) source order as the last tiebreaker. In the scenario, the layered `#app .btn.primary` rule loses to the unlayered `button` rule at step 2, so its three-part selector weight is never even counted. Interviewers ask this because `@layer` made the pre-specificity stages practically relevant: debugging "why does my high-specificity rule lose?" now requires knowing the pipeline, not just the ID/class/type columns.', 'codeprep', 'css-sa-cascade-resolution-flow');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (26, 1, 26, 'short-answer', 'Explain how the browser uses specificity to decide which conflicting rule wins, and where `!important` and source order fit in.', 'Specificity is scored in three columns — IDs, then classes/attributes/pseudo-classes, then element types/pseudo-elements — and the columns are compared left to right, so a higher column beats any number of lower ones (inline styles rank above all selectors). The most specific rule wins; only when specificity ties does source order decide, with the last declaration winning. `!important` is separate: it lifts a declaration into a higher-priority layer that overrides normal declarations regardless of specificity.', 'The cascade resolves conflicts by: importance (`!important` vs normal), then specificity, then source order. Specificity is an (inline, id, class, type) tuple compared column by column; a higher column wins outright. Ties fall through to whichever matching rule appears last in the source.', 'codeprep', 'css-sa-specificity-algorithm');
