INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (31, 2, 1, 'multiple-choice', 'What is the type of a value read from `process.env.PORT`?', '`string` (or `undefined` if unset)', 'Every value on `process.env` is a string (or `undefined` when the variable is not set). Numeric-looking values like `"3000"` are still strings, so you must convert with `Number(process.env.PORT)` before using them as numbers.', 'codeprep', 'node-mcq-process-env-type');
