INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (32, 2, 2, 'multiple-choice', 'In a CommonJS module (a `.js` file loaded with `require`), which of these is a real, module-scoped variable Node injects automatically?', '`__dirname`', 'Node wraps every CommonJS module in a function that receives `exports`, `require`, `module`, `__filename`, and `__dirname` as parameters, so `__dirname` is available without importing anything. `import.meta` only exists in ES modules; `window` is a browser global.', 'codeprep', 'node-mcq-dirname-commonjs');
INSERT INTO question_options (question_id, position, option_text) VALUES (32, 1, '`__dirname`');
