INSERT INTO question_options (question_id, position, option_text) VALUES (32, 4, '`window`');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (33, 2, 3, 'multiple-choice', 'An HTTP handler must send a 2 GB video file to the client. Which approach avoids holding the entire file in memory at once?', '`fs.createReadStream(path).pipe(res)` — stream the file to the response in chunks', '`createReadStream(...).pipe(res)` reads the file in fixed-size chunks (default ~64 KB) and writes each to the response as it arrives, so resident memory stays at roughly one chunk regardless of file size. `readFile`/`readFileSync` materialize all 2 GB as a single Buffer before sending. `pipe` also wires up backpressure, pausing the read when the socket can\'t keep up.', 'codeprep', 'node-mcq-stream-serve-large-file');
INSERT INTO question_options (question_id, position, option_text) VALUES (33, 1, '`res.end(fs.readFileSync(path))` — read the whole file synchronously, then send it in one write');
INSERT INTO question_options (question_id, position, option_text) VALUES (33, 2, '`res.end(await fs.promises.readFile(path))` — read the whole file asynchronously, then send it');
INSERT INTO question_options (question_id, position, option_text) VALUES (33, 3, '`fs.createReadStream(path).pipe(res)` — stream the file to the response in chunks');
INSERT INTO question_options (question_id, position, option_text) VALUES (33, 4, '`res.end(Buffer.alloc(2 ** 31))` — preallocate one buffer the size of the file, then send it');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (34, 2, 4, 'true-false', 'On current Node.js LTS, an unhandled promise rejection that is never caught will, by default, crash the process (non-zero exit).', 'True', 'Since Node 15 the default `--unhandled-rejections` mode is `throw`: an unhandled rejection is treated like an uncaught exception and terminates the process with a non-zero exit code. Earlier versions only printed a warning. Always attach a `.catch` or handle rejections in `async` code.', 'codeprep', 'node-tf-unhandled-rejection-exit');
INSERT INTO question_options (question_id, position, option_text) VALUES (34, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (34, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (35, 2, 5, 'multiple-choice', 'When you call `require("lodash")` (a bare specifier, not a relative path), where does Node look first?', 'In `node_modules` starting in the current directory, then walking up the parent directories', 'For a bare specifier, Node searches `./node_modules`, then `../node_modules`, then up the directory tree to the filesystem root, using the package\'s `main`/`exports` to pick the entry file. Global installs and `NODE_PATH` are only consulted after this local walk fails.', 'codeprep', 'node-mcq-require-resolution-order');
INSERT INTO question_options (question_id, position, option_text) VALUES (35, 1, 'In `node_modules` starting in the current directory, then walking up the parent directories');
INSERT INTO question_options (question_id, position, option_text) VALUES (35, 2, 'Only in the global npm install directory');
INSERT INTO question_options (question_id, position, option_text) VALUES (35, 3, 'In the current directory as a relative file `./lodash`');
INSERT INTO question_options (question_id, position, option_text) VALUES (35, 4, 'In `process.env.NODE_PATH` exclusively');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (36, 2, 6, 'multiple-choice', 'While writing to a writable stream, `stream.write(chunk)` returns `false`. What does that mean, and what should a careful producer do?', 'The internal buffer is past its `highWaterMark`; pause writing and wait for the `\'drain\'` event before continuing', 'A `false` return does not mean the write failed — the chunk is still accepted and queued. It signals that buffered data has exceeded `highWaterMark`, i.e. backpressure: keep writing and the buffer (and memory) grow unbounded. The correct response is to stop writing until the stream emits `\'drain\'`, then resume.', 'codeprep', 'node-mcq-write-returns-false');
INSERT INTO question_options (question_id, position, option_text) VALUES (36, 1, 'The write failed and the chunk was discarded; immediately re-send that same chunk on the next tick');
INSERT INTO question_options (question_id, position, option_text) VALUES (36, 2, 'The internal buffer is past its `highWaterMark`; pause writing and wait for the `\'drain\'` event before continuing');
INSERT INTO question_options (question_id, position, option_text) VALUES (36, 3, 'The stream has already ended; call `stream.end()` and discard any remaining chunks you meant to write');
INSERT INTO question_options (question_id, position, option_text) VALUES (36, 4, 'Nothing actionable — the return value is purely advisory and the stream safely buffers everything regardless of volume');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (37, 2, 7, 'true-false', 'A `500 Internal Server Error` status code indicates a problem on the client side.', 'False', '`5xx` codes are server errors — the server failed to fulfil an apparently valid request (RFC 9110 §15.6). Client-side mistakes are reported with `4xx` codes such as `400`, `401`, `403`, and `404`.', 'codeprep', 'http-tf-500-is-client-error');
INSERT INTO question_options (question_id, position, option_text) VALUES (37, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (37, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (38, 2, 8, 'true-false', 'A `GET` request is intended to retrieve data without changing server state.', 'True', '`GET` is a safe method: it is meant to be read-only with no intended side effects (RFC 9110 §9.3.1). This is why intermediaries are free to cache, prefetch, and retry `GET` requests — behaviour that would be unsafe for `POST`.', 'codeprep', 'http-tf-get-no-side-effects');
INSERT INTO question_options (question_id, position, option_text) VALUES (38, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (38, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (39, 2, 9, 'short-answer', 'Walk through a classic cookie-based session login end to end, from the user submitting credentials to a later authenticated request and then logout.', 'The client POSTs the username and password over HTTPS. The server verifies them, typically by comparing against a stored password hash. On success it creates a server-side session record — an opaque session id mapped to the user — in its store (memory, Redis, or a database). It returns that id to the browser in a `Set-Cookie` header marked `HttpOnly; Secure; SameSite`. The browser stores the cookie and automatically attaches it on every subsequent same-site request. On each request the server looks the session id up in its store to identify the user, so no credentials are re-sent — the auth state is stateful and lives on the server. At logout the server deletes the session record from the store and clears the cookie, so the next request is anonymous.', 'This is the stateful cookie-session lifecycle: credentials are exchanged once for an opaque server-side session id, the browser ambiently re-presents that id on each request, and the server dereferences it against its store to recover the user. It is deliberately the inverse of the stateless JWT model — the source of truth is the server record, which is why logout works by deleting that record, and why these sessions are trivially revocable where a stateless token is not.', 'codeprep', 'http-auth-sa-cookie-session-login-flow');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (40, 2, 10, 'short-answer', 'How do `Cache-Control: max-age` and an `ETag` work together to control HTTP caching?', '`Cache-Control: max-age` sets the freshness lifetime: while a cached response is within `max-age` it can be served directly with no network round trip. Once it goes stale, the cache revalidates using the `ETag` validator — it sends `If-None-Match` with the stored ETag, and the server replies `304 Not Modified` (reuse the cached copy) or `200` with fresh content. So `max-age` avoids requests entirely and the ETag makes the eventual revalidation cheap.', 'Freshness (`max-age`/`Expires`) decides when a cached response can be used without contacting the origin; validators (`ETag`/`Last-Modified`) decide what happens when it expires. Together they minimize both the number of requests and the bytes transferred on the requests that do happen (RFC 9111 §4.2, §4.3).', 'codeprep', 'http-sa-cache-control-revalidation');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (41, 2, 11, 'multiple-choice', 'Which `Cache-Control` directive guarantees that a response is **never written to any cache** (e.g. for a page showing private banking data)?', 'no-store', '`no-store` forbids any cache from storing the request or response at all (RFC 9111 §5.2.2.5). `no-cache` *does* allow storage but requires revalidation with the origin before reuse; `max-age=0` makes a stored response immediately stale (still revalidatable); `must-revalidate` only forbids serving stale responses once they expire.', 'codeprep', 'http-mcq-cache-no-store-vs-no-cache');
INSERT INTO question_options (question_id, position, option_text) VALUES (41, 1, 'no-cache');
INSERT INTO question_options (question_id, position, option_text) VALUES (41, 2, 'no-store');
INSERT INTO question_options (question_id, position, option_text) VALUES (41, 3, 'max-age=0');
INSERT INTO question_options (question_id, position, option_text) VALUES (41, 4, 'must-revalidate');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (42, 2, 12, 'multiple-choice', 'Which keyword removes duplicate rows from a `SELECT` result set?', '`DISTINCT`', '`SELECT DISTINCT` collapses rows that are identical across all selected columns into one. `UNIQUE` is a column/table constraint, not a query keyword, and `GROUP BY` aggregates rather than simply de-duplicating.', 'codeprep', 'sql-mcq-select-distinct');
INSERT INTO question_options (question_id, position, option_text) VALUES (42, 1, '`DISTINCT`');
INSERT INTO question_options (question_id, position, option_text) VALUES (42, 2, '`UNIQUE`');
INSERT INTO question_options (question_id, position, option_text) VALUES (42, 3, '`GROUP`');
INSERT INTO question_options (question_id, position, option_text) VALUES (42, 4, '`DEDUPE`');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (43, 2, 13, 'true-false', 'Third normal form (3NF) requires that no non-key column depends on another non-key column (no transitive dependencies on the primary key).', 'True', '3NF builds on 2NF and additionally forbids transitive dependencies: every non-key attribute must depend on the key, the whole key, and nothing but the key. Storing a `zip_code` and a `city` that is functionally determined by the `zip_code` in the same table is the classic 3NF violation, since `city` depends on `zip_code` rather than directly on the primary key.', 'codeprep', 'sql-tf-3nf-transitive');
INSERT INTO question_options (question_id, position, option_text) VALUES (43, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (43, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (44, 2, 14, 'true-false', 'For an `INNER JOIN`, swapping which table is written first (`A JOIN B` vs `B JOIN A`) changes which rows appear in the result.', 'False', '`INNER JOIN` is commutative with respect to its result set: `A INNER JOIN B ON …` and `B INNER JOIN A ON …` return the same rows (column ordering aside). This is not true for outer joins — `LEFT JOIN` and `RIGHT JOIN` keep different unmatched sides.', 'codeprep', 'sql-tf-inner-join-order');
INSERT INTO question_options (question_id, position, option_text) VALUES (44, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (44, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (45, 2, 15, 'short-answer', 'What is database normalization, and what problem does it solve?', 'Normalization is the process of structuring tables to reduce data redundancy and avoid update anomalies, typically by splitting data into related tables linked by keys so each fact is stored in exactly one place. Storing a value once means you update it once, so the data cannot become inconsistent across duplicated copies.', 'Normalization removes redundancy so each piece of data lives in one place, which eliminates insertion, update, and deletion anomalies. The trade-off is that highly normalized schemas need more joins to reassemble data, which is why read-heavy systems sometimes deliberately denormalize.', 'codeprep', 'sql-sa-normalization-purpose');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (46, 2, 16, 'multiple-choice', 'Using the pgvector extension, which query returns the 5 rows whose `embedding` is most similar to `$1` by L2 (Euclidean) distance?', '`SELECT * FROM items ORDER BY embedding <-> $1 LIMIT 5`', 'pgvector adds a `vector` column type and distance operators: `<->` is L2/Euclidean distance, `<=>` is cosine distance, and `<#>` is negative inner product. A k-nearest-neighbour search is expressed as `ORDER BY embedding <-> $query LIMIT k` — order by the chosen distance ascending and cap the result. With no index this is an exact sequential scan computing every distance; adding an approximate index (HNSW or IVFFlat) lets the same `ORDER BY ... LIMIT` query trade a little recall for a large speed-up. Equality (`=`), plain `DESC` ordering, and `GROUP BY` do not express nearest-neighbour search.', 'codeprep', 'sql-mcq-pgvector-knn');
INSERT INTO question_options (question_id, position, option_text) VALUES (46, 1, '`SELECT * FROM items ORDER BY embedding <-> $1 LIMIT 5`');
INSERT INTO question_options (question_id, position, option_text) VALUES (46, 2, '`SELECT * FROM items WHERE embedding = $1 LIMIT 5`');
INSERT INTO question_options (question_id, position, option_text) VALUES (46, 3, '`SELECT * FROM items ORDER BY embedding DESC LIMIT 5`');
INSERT INTO question_options (question_id, position, option_text) VALUES (46, 4, '`SELECT * FROM items GROUP BY embedding HAVING embedding <-> $1 LIMIT 5`');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (47, 2, 17, 'short-answer', 'A web app opens a fresh database connection for every incoming request and closes it after the response. Under load it slows down and the database hits its connection limit. What technique fixes this, and how does it work?', 'A connection pool fixes it: the app keeps a fixed set of already-open connections and hands one to each request, returning it to the pool when the request finishes instead of closing it. That removes the per-request cost of opening a connection (TCP handshake, TLS negotiation, authentication) and caps the number of concurrent connections to the database, so it is never overwhelmed even when requests spike.', 'Opening a connection is expensive (handshake, TLS, auth) and the database tolerates only a bounded number of them. A connection pool keeps a set of live connections, lends them to requests, and reclaims them on completion — eliminating per-request setup cost and bounding total concurrency. The pool size becomes the real concurrency limit, which is why it\'s tuned to what the database can handle rather than the number of app instances.', 'codeprep', 'sql-sa-connection-pooling');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (48, 2, 18, 'multiple-choice', 'Under the SQL standard, which is the lowest isolation level that prevents phantom reads?', '`SERIALIZABLE`', 'By the ANSI SQL definitions, `READ UNCOMMITTED` allows dirty reads, `READ COMMITTED` prevents those but allows non-repeatable reads, `REPEATABLE READ` prevents non-repeatable reads but still permits phantoms, and only `SERIALIZABLE` forbids phantom reads. (PostgreSQL\'s `REPEATABLE READ` is stronger than the standard and happens to block phantoms too, but the standard\'s guarantee starts at `SERIALIZABLE`.)', 'codeprep', 'sql-mcq-isolation-phantom');
INSERT INTO question_options (question_id, position, option_text) VALUES (48, 1, '`SERIALIZABLE`');
INSERT INTO question_options (question_id, position, option_text) VALUES (48, 2, '`REPEATABLE READ`');
INSERT INTO question_options (question_id, position, option_text) VALUES (48, 3, '`READ COMMITTED`');
INSERT INTO question_options (question_id, position, option_text) VALUES (48, 4, '`READ UNCOMMITTED`');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (49, 2, 19, 'short-answer', 'Trace what a relational database does between receiving a `SELECT` as raw text and returning rows. Name the main stages in order.', 'First it parses the SQL text into a syntax tree and validates the names and types against the catalog. Then the optimizer (planner) enumerates candidate execution plans — which indexes to use, join order and join methods — and picks the one with the lowest estimated cost. Finally the executor runs that chosen plan, reading from tables and indexes and streaming the result rows back to the client.', 'The pipeline is parse → plan/optimize → execute. Parsing turns text into a validated tree; the optimizer chooses among possible plans by estimated cost (index vs sequential scan, join order/method); the executor then runs the winning plan and returns rows. `EXPLAIN` shows the plan the optimizer picked at the middle stage, which is why reading it is the first move when a query is slow.', 'codeprep', 'sql-sa-query-execution-flow');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (50, 2, 20, 'multiple-choice', 'Your API runs on a fleet behind a round-robin load balancer, but users intermittently get logged out as requests land on different nodes. The team stores session state in each node\'s local memory. What is the **single most important** change to enable safe horizontal scaling?', 'Move session state out of the app process into a shared store (e.g. Redis) so any node can serve any request', 'The root problem is that the app nodes are **stateful**: each holds session data only it can see. Externalising state to a shared store makes the nodes interchangeable, which is the precondition for horizontal scaling and for free rolling deploys and failover. Sticky sessions are a workaround, not a fix — they pin users to a node, so a deploy or crash still drops their session and they defeat even load distribution. Vertical scaling (more RAM) raises the ceiling but keeps the state trapped on one box, so the cross-node inconsistency remains. A CDN caches public, cacheable responses; per-user session data is neither, so it does nothing here.', 'codeprep', 'sd-mcq-stateless-horizontal-scale');
INSERT INTO question_options (question_id, position, option_text) VALUES (50, 1, 'Move session state out of the app process into a shared store (e.g. Redis) so any node can serve any request');
INSERT INTO question_options (question_id, position, option_text) VALUES (50, 2, 'Enable sticky sessions on the load balancer and keep state in local memory');
INSERT INTO question_options (question_id, position, option_text) VALUES (50, 3, 'Scale each node vertically with more RAM so sessions never get evicted');
INSERT INTO question_options (question_id, position, option_text) VALUES (50, 4, 'Add a CDN in front of the API to cache the session responses');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (51, 2, 21, 'short-answer', 'Contrast **horizontal** and **vertical** scaling, and describe when each hits a wall.', 'Vertical scaling (scaling up) means giving one machine more CPU, memory, or disk; it is simple and needs no application changes, but it hits a wall at the largest available machine size and leaves you with a single point of failure. Horizontal scaling (scaling out) means adding more machines behind a load balancer; it scales far beyond one box and improves availability, but it hits a wall when shared state gets in the way — you need stateless services, a way to coordinate or shard data, and you take on distributed-systems complexity. Most large systems scale out the stateless tier and reserve scale-up for the database until sharding becomes necessary.', '**Vertical** scaling (up) adds resources to one node — easy and transparent to the app, but bounded by the biggest machine and exposed to a single point of failure. **Horizontal** scaling (out) adds nodes behind a load balancer — effectively unbounded and more available, but it forces statelessness, data partitioning/replication, and distributed coordination. The pragmatic pattern is a stateless app tier that scales out freely, with the harder-to-distribute data layer scaled up first and sharded only when forced.', 'codeprep', 'sd-sa-horizontal-vertical-scaling');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (52, 2, 22, 'multiple-choice', 'An API must allow clients a sustained rate of 10 req/s but also tolerate **short bursts** (e.g. a client firing 50 requests after being idle). Which rate-limiting algorithm naturally supports this?', 'Token bucket', '**Token bucket** refills tokens at the sustained rate and lets unused tokens accumulate up to the bucket size, so an idle client banks capacity and can spend it in a burst — exactly the behaviour required. A **leaky bucket** smooths output to a fixed drain rate, deliberately flattening bursts, which is the opposite of what we want. A **fixed window counter** is bursty in the wrong way: it permits double the limit across a window boundary while still rejecting legitimate bursts inside a window. A concurrency semaphore of 1 limits parallelism, not request rate, and would serialise the client rather than rate-limit it.', 'codeprep', 'sd-mcq-token-bucket-vs-leaky');
INSERT INTO question_options (question_id, position, option_text) VALUES (52, 1, 'Token bucket');
INSERT INTO question_options (question_id, position, option_text) VALUES (52, 2, 'Leaky bucket (as a queue with a fixed drain rate)');
INSERT INTO question_options (question_id, position, option_text) VALUES (52, 3, 'Fixed window counter');
INSERT INTO question_options (question_id, position, option_text) VALUES (52, 4, 'A hard concurrency semaphore of 1');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (53, 2, 23, 'short-answer', 'What is a **circuit breaker**, and what problem does it prevent?', 'A circuit breaker wraps calls to a downstream dependency and trips open after a threshold of failures, so subsequent calls fail fast instead of waiting on a doomed request. This prevents a cascading failure: without it, a slow or down dependency would tie up threads and connections in the caller, exhaust its resources, and propagate the outage upstream. After a cooldown the breaker moves to half-open and lets a probe request through; if it succeeds the breaker closes and normal traffic resumes, otherwise it re-opens.', 'A **circuit breaker** monitors failures to a dependency and, past a threshold, opens to make calls **fail fast** rather than block. This stops a single unhealthy downstream from exhausting the caller\'s threads/connections and cascading the failure system-wide. Its three states — closed (normal), open (short-circuiting), half-open (trial requests) — let it recover automatically, and it is typically paired with timeouts, retries with backoff, and a fallback response.', 'codeprep', 'sd-sa-circuit-breaker');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (54, 2, 24, 'true-false', 'An open circuit breaker stays open permanently until an operator manually resets it.', 'False', 'A circuit breaker is self-healing. After the open timeout elapses it transitions to **half-open**, allowing a limited number of trial requests through. If those succeed it closes and resumes normal traffic; if they fail it re-opens and waits again. This automatic probing is the whole point — it lets the system recover without human intervention while still shielding a struggling downstream from a thundering herd.', 'codeprep', 'sd-tf-circuit-breaker-half-open');
INSERT INTO question_options (question_id, position, option_text) VALUES (54, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (54, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (55, 2, 25, 'multiple-choice', 'A request that fans out across six microservices is intermittently slow, and per-service dashboards each look healthy in isolation. Which observability signal is **purpose-built** to locate where the latency is spent across that single request\'s path?', 'Distributed tracing with a propagated trace/span context across all services', '**Distributed tracing** stitches together the spans of one request as it crosses service boundaries via a propagated trace context, so you can see exactly which hop consumed the time — the precise need when each service looks fine on its own. Aggregate **metrics** tell you *that* p95 is high but average away the individual slow request and cannot attribute latency across the chain. **Logs** are per-service and unordered relative to each other; without a shared trace id you cannot reliably reconstruct one request\'s journey across all six. A **health check** only answers up/down liveness and says nothing about per-request latency distribution. Metrics, logs, and traces are complementary, but tracing is the one built for cross-service request attribution.', 'codeprep', 'sd-mcq-traces-vs-logs-metrics');
INSERT INTO question_options (question_id, position, option_text) VALUES (55, 1, 'Distributed tracing with a propagated trace/span context across all services');
INSERT INTO question_options (question_id, position, option_text) VALUES (55, 2, 'Per-service aggregate latency metrics (p50/p95 counters)');
INSERT INTO question_options (question_id, position, option_text) VALUES (55, 3, 'Structured logs grepped independently on each service');
INSERT INTO question_options (question_id, position, option_text) VALUES (55, 4, 'An uptime health-check endpoint polled every 30 seconds');
