INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (61, 3, 1, 'short-answer', 'Why do production chat UIs stream tokens, and what does streaming improve versus what it does not?', 'Streaming sends tokens to the client as they\'re generated rather than waiting for the full completion, which dramatically lowers perceived latency — the user sees the first token (time-to-first-token) in a fraction of a second instead of staring at a spinner for the whole response. What it does not change is the total time to finish or the total cost: the same number of tokens are generated and billed, so streaming improves perceived responsiveness, not throughput or price.', 'Streaming is purely a latency-perception win: tokens are flushed incrementally so the user gets immediate feedback (low time-to-first-token), which matters a lot for long generations. It does not reduce total generation time, total tokens, or cost — those are fixed by the output length. It does add engineering cost: you must handle partial output, parse incrementally, and deal with mid-stream errors and cancellation.', 'codeprep', 'ai-sa-streaming-why');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (62, 3, 2, 'multiple-choice', 'When an LLM "calls a tool" (function calling), what does the model itself actually produce in the API response?', 'A structured request naming the tool and its arguments; your application runs it and feeds the result back', 'Function/tool calling is a protocol, not remote execution: given your tool definitions (name, description, JSON-Schema parameters), the model decides *whether* to call one and emits a structured tool-call with arguments. **Your** code executes the tool, then sends the result back as a tool/function message so the model can use it in its next turn. The provider does not run your code (a) — it has no access to your database or APIs. The model returns structured arguments, not executable code to `eval` (c); `eval`-ing model output would be a serious injection risk. And it is a concrete, parseable call, not a vague wish (d).', 'codeprep', 'ai-mcq-tool-calling-flow');
INSERT INTO question_options (question_id, position, option_text) VALUES (62, 1, 'The model executes the function on the provider\'s servers and returns the result');
INSERT INTO question_options (question_id, position, option_text) VALUES (62, 2, 'A structured request naming the tool and its arguments; your application runs it and feeds the result back');
INSERT INTO question_options (question_id, position, option_text) VALUES (62, 3, 'Raw Python that your runtime must `eval` to get the answer');
INSERT INTO question_options (question_id, position, option_text) VALUES (62, 4, 'A natural-language description of the function it wishes existed');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (63, 3, 3, 'short-answer', 'What is prompt caching, and how should you structure a prompt to benefit from it?', 'Prompt caching lets the provider reuse the computed attention state for a large, stable prefix of your prompt (system instructions, few-shot examples, a long document) across requests, so repeated calls are cheaper and lower latency because the cached prefix is billed at a reduced rate and skips recomputation. To benefit, put the stable, reused content at the front of the prompt and the variable, per-request content (the user\'s question) at the end — caching keys off the longest matching prefix.', 'Caching works on a prefix match: the provider stores the key/value attention state for an unchanged leading span and reuses it on subsequent calls, cutting both cost and time-to-first-token. The practical rule is order-dependent — keep the big invariant blob (system prompt, tool definitions, long context document, few-shot exemplars) at the start and anything that changes per request at the tail, otherwise the cache misses on every call.', 'codeprep', 'ai-sa-prompt-caching');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (64, 3, 4, 'short-answer', 'What does \'agentic RAG\' add over a classic retrieve-then-generate pipeline, and what does that flexibility cost?', 'Agentic RAG makes retrieval a tool that an LLM agent controls rather than a fixed first step. The agent can decide whether to retrieve at all, reformulate or decompose the query, retrieve iteratively for multi-hop questions, choose among multiple sources or indexes, and judge whether the retrieved context is sufficient before answering — re-querying when it is not. That handles ambiguous and multi-hop queries a single static top-k retrieval gets wrong. The cost is more LLM calls per question, so higher latency and token cost, more non-determinism, and harder evaluation and tracing; it can also loop or over-retrieve. So you reach for it when query complexity justifies the overhead, and keep static RAG for simple single-fact lookups.', 'The win is model-controlled, iterative, multi-source retrieval that adapts to the query — deciding whether to retrieve, reformulating, decomposing, and re-querying until the context is sufficient. The price is extra LLM round-trips: latency, token cost, non-determinism, and harder eval/tracing, with a risk of looping. Match the architecture to query complexity; static retrieve-then-generate stays the right default for simple lookups.', 'codeprep', 'ai-sa-agentic-rag-tradeoffs');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (65, 3, 5, 'short-answer', 'Why do RAG evaluation frameworks (e.g. RAGAS) score the retrieval stage and the generation stage with separate metrics instead of one end-to-end answer-quality score?', 'Because a single end-to-end score tells you the answer was bad but not why, and the two stages fail for different reasons with different fixes. Retrieval metrics like context recall and context precision check whether the right, relevant passages were fetched at all; generation metrics like faithfulness and answer relevance check whether the model grounded its answer in that context and actually addressed the question. Decomposing localizes the fault: if context recall is low, the needed passage was never retrieved, so you fix chunking, the embedding model, or reranking; if recall is fine but faithfulness is low, the evidence was present but the model ignored or contradicted it, so you fix the prompt or the model. Separate metrics turn \'the answer is wrong\' into an actionable diagnosis.', 'A blended score can\'t separate \'we never fetched the right evidence\' (retrieval — low context recall) from \'we had the evidence and still got it wrong\' (generation — low faithfulness). Those have different fixes — chunking/embeddings/reranking versus prompt/model — so component metrics convert a failing answer into a specific stage you can act on.', 'codeprep', 'ai-sa-decompose-rag-eval');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (66, 3, 6, 'true-false', 'As of Python 3.7, a regular `dict` preserves insertion order when iterated.', 'True', 'Ordered iteration by insertion became a guaranteed language feature in Python 3.7 (it was a CPython implementation detail in 3.6). Iterating a `dict`, its `keys()`, `values()`, or `items()` yields entries in the order they were first inserted, so `OrderedDict` is now needed only for its extra ordering methods.', 'codeprep', 'py-tf-dict-insertion-order');
INSERT INTO question_options (question_id, position, option_text) VALUES (66, 1, 'True');
INSERT INTO question_options (question_id, position, option_text) VALUES (66, 2, 'False');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (67, 3, 7, 'multiple-choice', 'What does `isinstance(True, int)` return, and why?', '`True` — `bool` is a subclass of `int`, so `True` behaves as `1` and `False` as `0`', '`bool` is defined as a subclass of `int` in Python, so `isinstance(True, int)` is `True` and booleans participate in arithmetic — `True + True` is `2`. This is why `isinstance(x, int)` accidentally accepts booleans, and why summing a list of bools counts the `True` values.', 'codeprep', 'py-mcq-bool-is-int-subclass');
INSERT INTO question_options (question_id, position, option_text) VALUES (67, 1, '`True` — `bool` is a subclass of `int`, so `True` behaves as `1` and `False` as `0`');
INSERT INTO question_options (question_id, position, option_text) VALUES (67, 2, '`False` — `bool` and `int` are unrelated types');
INSERT INTO question_options (question_id, position, option_text) VALUES (67, 3, '`False` — `int` is a subclass of `bool`, not the other way around');
INSERT INTO question_options (question_id, position, option_text) VALUES (67, 4, 'It raises a `TypeError` because `True` is not a class instance');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (68, 3, 8, 'multiple-choice', 'What distinguishes a `@classmethod` from a `@staticmethod`?', 'A classmethod receives the class as an implicit first argument (`cls`); a staticmethod receives no implicit first argument at all', '`@classmethod` binds the class to an implicit first parameter `cls`, which is why it can reference class attributes or act as an alternate constructor and respects subclassing. `@staticmethod` gets no implicit argument — it is just a plain function namespaced on the class. Both can be called via the class or an instance.', 'codeprep', 'py-mcq-classmethod-vs-staticmethod');
INSERT INTO question_options (question_id, position, option_text) VALUES (68, 1, 'A classmethod receives the class as an implicit first argument (`cls`); a staticmethod receives no implicit first argument at all');
INSERT INTO question_options (question_id, position, option_text) VALUES (68, 2, 'A staticmethod receives the instance (`self`); a classmethod receives nothing');
INSERT INTO question_options (question_id, position, option_text) VALUES (68, 3, 'A classmethod can be called on the class but a staticmethod can only be called on an instance');
INSERT INTO question_options (question_id, position, option_text) VALUES (68, 4, 'There is no difference; the two decorators are aliases');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (69, 3, 9, 'short-answer', 'What is the GIL, and what does it mean for CPU-bound versus I/O-bound work using threads?', 'The Global Interpreter Lock is a mutex in CPython that lets only one thread execute Python bytecode at a time. For CPU-bound work, threads can\'t run in parallel on multiple cores, so you reach for multiprocessing (separate interpreters) instead. For I/O-bound work the lock is released while a thread waits on the network or disk, so threads still overlap usefully and give real concurrency.', 'The GIL serialises Python bytecode execution per process, so CPU-bound threads don\'t scale across cores — use multiprocessing for those. I/O-bound threads still help because the GIL is released during blocking I/O, letting other threads run.', 'codeprep', 'py-short-gil');
INSERT INTO questions (id, quiz_id, position, type, text, answer, explanation, source, source_ref) VALUES (70, 3, 10, 'multiple-choice', 'Given this diamond, what does `D().who()` return?\n\n```python\nclass A:\n    def who(self): return "A"\nclass B(A):\n    def who(self): return "B"\nclass C(A):\n    def who(self): return "C"\nclass D(B, C):\n    pass\n```', '`"B"`', 'Python resolves attributes along the C3-linearized method resolution order, which for `D(B, C)` is `D -> B -> C -> A -> object`. The first class on that chain defining `who` is `B`, so `D().who()` returns `"B"`. The MRO is what makes cooperative `super()` calls work without re-running shared bases.', 'codeprep', 'py-mcq-mro-c3');
INSERT INTO question_options (question_id, position, option_text) VALUES (70, 1, '`"B"`');
INSERT INTO question_options (question_id, position, option_text) VALUES (70, 2, '`"C"`');
INSERT INTO question_options (question_id, position, option_text) VALUES (70, 3, '`"A"`');
INSERT INTO question_options (question_id, position, option_text) VALUES (70, 4, 'It raises a `TypeError` for ambiguous inheritance');
